/// ── @for item in ... ──
__omni_effect(() => {
  const data = NotificationStore_notifications.value;
  const tpl = __omni_el("el-for-444-tpl");
  const ctr = __omni_el("el-for-444-ctr");
  if (!tpl || !ctr) return;
  // Clear existing rendered items
  ctr.querySelectorAll('[data-for-item]').forEach(el => el.remove());
  if (!data || data.length === 0) return;
  data.forEach((item, _idx) => {
    const clone = tpl.content.firstElementChild.cloneNode(true);
    clone.setAttribute('data-for-item', _idx);
    // Bind text interpolation markers
    clone.querySelectorAll('[data-bind-text]').forEach(el => {
      const expr = el.getAttribute('data-bind-text');
      if (expr) {
        try {
          // Use Function constructor to evaluate expressions like `item.name`
          el.textContent = String((new Function('item', 'return ' + expr))(item));
        } catch(e) { el.textContent = ''; }
      }
    });
    // Bind data-* attribute interpolation
    clone.querySelectorAll('[data-text],[data-value],[data-label],[data-key]').forEach(el => {
      Array.from(el.attributes).forEach(attr => {
        if (attr.name.startsWith('data-') && attr.value.includes('{')) {
          try {
            // Convert {item} patterns to ${item} for JS template literals
            const jsTemplate = attr.value.replace(/\{(\w+)\}/g, '${$1}');
            const resolved = (new Function('item', 'return `' + jsTemplate + '`'))(item);
            el.setAttribute(attr.name, resolved);
          } catch(e) { /* keep original */ }
        }
      });
    });
    ctr.appendChild(clone);
  });
});
